tool.command:

  ln -f -s ${input_tpr_path} ${input_tpr_path}_`echo $$`.${input_tpr_path.ext};

  ln -f -s ${input_ndx_path} ${input_ndx_path}_`echo $$`.${input_ndx_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

convert_tpr

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__extend__dq__:${properties.extend},__dq__until__dq__:${properties.until},__dq__nsteps__dq__:${properties.nsteps},__dq__output_group__dq__:__dq__${properties.output_group}__dq__,__dq__gmx_lib__dq__:__dq__${properties.gmx_lib}__dq__,__dq__binary_path__dq__:__dq__${properties.binary_path}__dq____cc____cc__'
  #end if

  #if str($input_tpr_path) != 'None':
    --input_tpr_path ${input_tpr_path}_`echo $$`.${input_tpr_path.ext}
  #end if

  #if str($input_ndx_path) != 'None':
    --input_ndx_path ${input_ndx_path}_`echo $$`.${input_ndx_path.ext}
  #end if


  --output_tpr_path $outname_output_tpr_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_tpr_path}_`echo $$`.${input_tpr_path.ext};

  rm -f ${input_ndx_path}_`echo $$`.${input_ndx_path.ext};


  if test -f $outname_output_tpr_path; then mv $outname_output_tpr_path $output_tpr_path; fi;
